-- Generated by `chainindex dbt` from chains/ethereum.yaml and abis/UniswapV3Factory.json. Do not edit: change the chain file or ABI and regenerate.
-- FeeAmountEnabled(uint24,int24)
{{ config(
    materialized='view',
    schema='events_ethereum',
    alias='uniswap_v3_factory__fee_amount_enabled',
    tags=['chains', 'chain_ethereum'],
) }}

select
    toUInt64(1) as chain_id,
    address,
    block_number,
    block_time,
    block_hash,
    transaction_hash,
    transaction_index,
    log_index,
    inserted_at,
    toUInt32(reinterpretAsUInt256(reverse(unhex(substring(topic1, 3, 64))))) as fee,
    toInt32(reinterpretAsInt256(reverse(unhex(substring(topic2, 3, 64))))) as tick_spacing
from {{ source('chain_ethereum', 'logs') }}
where topic0 = '0xc66a3fdf07232cdd185febcc6579d408c241b47ae2f9907d84be655141eeaecc'
  and address in (select address from {{ ref('ethereum__contracts') }} where contract = 'uniswap_v3_factory')
  and (block_number, block_hash) not in (
    select block_number, block_hash from {{ source('chain_ethereum', 'orphaned_blocks') }}
  )
